import type { Tool } from "./config.ts";

export type ResolvedTool = Tool & {
  desc: string | null;
  bestUrl: string;
};

const GENERATED =
  "<!-- Generated by scripts/generate.ts from pzz.json — do not edit by hand. -->";

export function renderToolbox(tools: ResolvedTool[]): string {
  return [
    "# Frontend toolbox",
    "",
    "Preferred tools for UI/frontend work. Pick the row matching the task, then open its canonical page.",
    "",
    "| Task | Tool | Canonical page |",
    "| --- | --- | --- |",
    ...tools.map((t) => `| ${t.task} | ${t.name} | ${t.bestUrl} |`),
    "",
    "## Details",
    "",
    ...tools.map(
      (t) =>
        `- **[${t.name}](${t.bestUrl})** — ${t.task}${t.desc ? `. ${t.desc}` : ""}`,
    ),
    "",
    GENERATED,
    "",
  ].join("\n");
}

export function renderSkill(tools: ResolvedTool[], docUrl: string): string {
  const tasks = tools.map((t) => t.task).join("; ");
  const rows = tools
    .map((t) => `| ${t.task} | ${t.name} | ${t.bestUrl} |`)
    .join("\n");
  return `---
name: frontend-toolbox
description: Preferred UI/frontend tools. Use whenever a task involves ${tasks}.
---

# Frontend toolbox

Default tools for UI work. Pick the row that matches the task, then open its
canonical page before using the tool.

| Task | Tool | Canonical page |
| --- | --- | --- |
${rows}

The always-current list lives in the repository:
\`${docUrl}\`.
Treat it as the source of truth and refresh this table from it when it changes.

${GENERATED}
`;
}
